NATIVE_FILES=['r_au.npy','theta_rad.npy','phi_rad.npy','r_faces_au.npy','theta_faces_rad.npy','phi_faces_rad.npy','Br_faces_nt.npy','Btheta_faces_nt.npy','Bphi_faces_nt.npy']

def utc():return datetime.now(timezone.utc).isoformat()
def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
    return h.hexdigest()
def atomic(path,data):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name('.'+path.name+f'.{os.getpid()}.tmp')
    tmp.write_text(json.dumps(data,indent=2,allow_nan=False)+'\n');tmp.replace(path)
def cfgread(path):
    return {k.strip():v.strip() for k,v in (line.split('=',1) for line in path.read_text().splitlines() if '=' in line and not line.lstrip().startswith('#'))}
def readjson(path):return json.loads(path.read_text())
def resolved_input(value,folder):
    p=Path(value)
    if p.is_absolute():return p
    # Native production inputs are absolute. For a relative input, native Athena
    # evaluates it from its case working directory, so reproduce that convention.
    return (folder/p).resolve()
def hashes(paths):return {str(p.resolve()):sha(p) for p in paths}
def signature(record):return hashlib.sha256(json.dumps(record,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def volume_manifest(folder):
    path=folder/'volume_snapshots.csv'
    if not path.exists():path=folder/'snapshots.csv'
    with path.open() as f:rows=list(csv.DictReader(f))
    if not rows:raise ValueError('Empty3D volume manifest')
    # Movie snapshots.csv can describe2Dplanes; its legacy use is accepted only
    # when the referenced final array actually has the native eight-field shape.
    candidates=[]
    for row in rows:
        p=folder/row.get('file',row.get('filename',''))
        z=np.load(p,mmap_mode='r')
        if z.ndim==4 and z.shape[-1]==8:candidates.append((float(row['day']),p,tuple(z.shape)))
        del z
    if not candidates:raise ValueError('No native3D eight-field volume in manifest')
    day,p,shape=max(candidates,key=lambda x:x[0])
    if np.prod(shape[:3])>MAX_CELLS:raise ValueError(f'Volume exceeds bounded{MAX_CELLS}cell audit')
    return path,day,p,shape

def completion(folder):
    """Independent endpoint/marker checks; an unsuccessful run is never audited."""
    result={'path':str(folder),'status':'excluded','execution_complete':False,'reasons':[]}
    status_path=folder/'candidate_status.json'
    if status_path.exists():
        status=readjson(status_path);result['recorded_status']=status
        if status.get('execution_complete') is False or status.get('status') in ['unrun','running','failed','interrupted','unsupported']:
            result['reasons'].append('Controller explicitly records an incomplete/failed/unrun case')
            return result
    try:
        cfg=cfgread(folder/'run.cfg');stats=readjson(folder/'statistics.json')
        trace=np.genfromtxt(folder/'ct_trace.csv',delimiter=',',names=True,ndmin=1)
        if not len(trace):raise ValueError('Empty accepted-step trace')
        days=trace['day'];start=float(cfg['start_day']);end=float(cfg['end_day'])
        if not (np.all(np.isfinite(days)) and np.all(np.diff(days)>0) and abs(days[0]-start)<=1e-10 and abs(days[-1]-end)<=1e-10):raise ValueError('Accepted trace does not cover configured start/end monotonically')
        steps=int(stats['steps'])
        if steps<=0 or len(trace)!=steps+1 or int(stats['stage_calls'])!=2*steps:raise ValueError('Accepted-step/stage/trace-row counts disagree')
        manifest,day,volume,shape=volume_manifest(folder)
        if abs(day-end)>1e-10:raise ValueError('Final3D volume epoch does not match configured endpoint')
        for name in NATIVE_FILES:
            if not (folder/name).is_file():raise ValueError('Missing native geometry/face array: '+name)
        usage=readjson(folder/'runner_usage.json') if (folder/'runner_usage.json').exists() else {}
        if usage.get('exit_code',usage.get('returncode',0)) not in [0,None] or usage.get('termination_reason'):
            raise ValueError('Runner records failed/terminated execution')
        result.update(status='completed',execution_complete=True,cfg=cfg,statistics=stats,usage=usage,volume_manifest=str(manifest),volume_day=day,volume_path=str(volume),shape=list(shape),accepted_trace_rows=len(trace),start_day=float(days[0]),end_day=float(days[-1]),completion_evidence='Controller marker plus independent configured endpoints/counts/final3D epoch checks' if status_path.exists() else 'Legacy completion inferred from configured endpoints/counts/final3D epoch; no controller marker')
    except (OSError,ValueError,KeyError,TypeError,IndexError) as e:result['reasons'].append(str(e))
    return result

def cache_audit(folder,kind,paths,cache_dir,function):
    dependencies=hashes(paths);key=signature({'schema':SCHEMA,'kind':kind,'inputs':dependencies})
    cache=cache_dir/(folder.name+'_'+signature(str(folder))[:10]+'_'+kind+'_'+key+'.json')
    if cache.exists():
        value=readjson(cache)
        if value.get('signature')!=key or value.get('inputs_sha256')!=dependencies:raise ValueError('Cache receipt mismatch')
        return value['result'],{'hit':True,'file':str(cache),'signature':key}
    value=function()
    if hashes(paths)!=dependencies:raise ValueError('Audit inputs changed during read; no cache/result accepted')
    atomic(cache,{'schema':SCHEMA,'created_utc':utc(),'signature':key,'inputs_sha256':dependencies,'result':value})
    return value,{'hit':False,'file':str(cache),'signature':key}

def field_audit(folder,record,cache_dir):
    cfg=record['cfg']
    paths=[Path(record['volume_path']),Path(record['volume_manifest']),folder/'run.cfg',folder/'ct_trace.csv']+[folder/n for n in NATIVE_FILES]
    paths += [ROOT/'solver/audit_ct_fields.py',ROOT/'scripts/audit_entropy_bound.py',Path(__file__)]
    if (folder/'probe.csv').exists():paths.append(folder/'probe.csv')
    if cfg.get('boundary_map_csv'):paths.append(resolved_input(cfg['boundary_map_csv'],folder))
    if cfg.get('cme_boundary_csv'):paths.append(resolved_input(cfg['cme_boundary_csv'],folder))
    def work():
        # Keep the optional large entropy pass out of the native-face helper's
        # live-array scope; helper arithmetic is otherwise unchanged.
        result=audit_ct_fields.audit(folder,include_entropy=False)
        if result['volume_sha256']!=sha(Path(record['volume_path'])):raise ValueError('Native helper did not audit the final3D manifest volume')
        if cfg.get('boundary_speed_thermo_closure')=='1' and not cfg.get('cme_boundary_csv'):
            result['entropy_bound']=audit_ct_fields.entropy_audit(folder)
        return result
    return cache_audit(folder,'native_fields',paths,cache_dir,work)

def safe_ratio(numerator,denominator):return float(numerator/denominator) if denominator else (0.0 if numerator==0 else None)
def gate(value,target,comparison='<=' ,note=None):
    valid=value is not None and math.isfinite(float(value))
    if not valid:passed=None
    elif comparison=='<=':passed=bool(value<=target)
    elif comparison=='>':passed=bool(value>target)
    elif comparison=='>=':passed=bool(value>=target)
    else:raise ValueError('Unknown gate comparison: '+comparison)
    return {'value':value,'comparison':comparison,'target':target,'passed':passed,**({'note':note} if note else {})}

