      'actual_trace_local_boundary_work':gate(float(s['max_actual_trace_work_discrepancy_over_total_energy_flux']),thresholds['local_boundary_work_mismatch_over_total_energy_flux_target']),
      'actual_trace_integrated_boundary_work':gate(abs(signed_work) if signed_work is not None else None,thresholds['integrated_boundary_work_mismatch_over_CT_work_target'],note='Undefined if CT work is zero but hydro-subtracted numerical work is nonzero; no artificial denominator'),
      'all_volume_fields_finite':{'value':fields['all_volume_fields_finite'],'passed':fields['all_volume_fields_finite']},
      'all_volume_density_pressure_positive':{'value':fields['all_volume_density_pressure_positive'],'passed':fields['all_volume_density_pressure_positive']},
      'all_accepted_cell_density_pressure_positive':{'minimum_density_cm3':s['minimum_density_cm3'],'minimum_pressure_code':s['minimum_pressure_code'],'passed':s['minimum_density_cm3']>0 and s['minimum_pressure_code']>0},
      'accepted_physical_stage_count':{'value':stages,'target':2*steps,'passed':stages==2*steps},
    }
    if 'native_stage_rhs_calls' in s:g['native_all_block_stage_count']={'value':int(s['native_stage_rhs_calls']),'target':2*blocks*steps,'passed':int(s['native_stage_rhs_calls'])==2*blocks*steps}
    entropy=fields.get('entropy_bound')
    thermal={'minimum_temperature_K':fields['minimum_temperature_K'],'number_cells_below1000K':fields['number_cells_below1000K'],'coverage':'Final3D volume; accepted-step minima track density and pressure separately, not their cellwise temperature ratio at every prior state','physical_entropy_bound':gate(entropy['minimum_proxy_over_bound'],plan['thermal_diagnostic']['desired_final_minimum_ratio'],'>=') if entropy else {'passed':None,'note':'Ambient analytic bound not applicable without closure or with CME cones; no failure/pass inferred'}}
    return {'gates':g,'all_formulation_gates_passed':all(x['passed'] is True for x in g.values()),'all_applicable_formulation_gates_passed':all(x['passed'] is True for x in g.values() if x['passed'] is not None),'any_undefined_gate':any(x['passed'] is None for x in g.values()),'actual_trace_integrated_work_signed_relative_difference':signed_work,'thermal':thermal,'scope':'No convergence, spacecraft validation, scientific-reference selection or confidence-interval claim follows from these formulation checks.'}

def load_curve(folder):
    a=postprocess.own_case(folder.name,folder=folder)
    if len(a['day'])<2 or not np.all(np.diff(a['day'])>0):raise ValueError('Comet probe0 must contain at least two strictly increasing epochs')
    for key in a:
        if not np.all(np.isfinite(a[key])):raise ValueError('Nonfinite comet curve: '+key)
    ep=postprocess.tsv(ROOT/'observations/ephemeris_comet.tsv')
    if a['day'][0]<ep['mjd_utc'][0]-postprocess.ORIGIN-1e-10 or a['day'][-1]>ep['mjd_utc'][-1]-postprocess.ORIGIN+1e-10:raise ValueError('Comet velocity would extrapolate its ephemeris')
    return observer_case(a,{'time_convention':'observer_arrival'})

def coverage(a,spans):return bool(all(start>=a['day'][0]-1e-8 and stop<=a['day'][-1]+1e-8 for start,stop in spans))
def extrema(a,spans):
    if not coverage(a,spans):raise ValueError('Refusing temporal extrapolation in extrema')
    t=np.unique(np.concatenate([np.r_[s,a['day'][(a['day']>s)&(a['day']<e)],e] for s,e in spans]))
    result={}
    for k in OBS_FIELDS:
        z=np.interp(t,a['day'],a[k]);lo=int(np.argmin(z));hi=int(np.argmax(z))
        result[k]={'min':float(z[lo]),'max':float(z[hi]),'minimum_arrival_day':float(t[lo]),'maximum_arrival_day':float(t[hi])}
    return result

def observer_audit(folder,cache_dir):
    files=[folder/'probe.csv',ROOT/'scripts/postprocess.py',ROOT/'scripts/observer_clock.py',ROOT/'observations/light_travel_time_audit.py',ROOT/'observations/ephemeris_comet.tsv',ROOT/'observations/ephemeris_wind.tsv',ROOT/'observations/coordinate_system.json',ROOT/'observations/xmm_gtis.tsv',Path(__file__)]
    def work():
        a=load_curve(folder);gti=postprocess.tsv(ROOT/'observations/xmm_gtis.tsv');gti=gti[gti['detector']=='pn']
        spans=[(float(s-postprocess.ORIGIN),float(e-postprocess.ORIGIN)) for s,e in zip(gti['start_mjd_utc'],gti['stop_mjd_utc'])]
        result={'time_convention':'observer_arrival','Earth_proxy':'Geometric Earth ephemeris; same-emission-epoch comet velocity; no fitted phase/time offset','observer_arrival_day_coverage':[float(a['day'][0]),float(a['day'][-1])],'comet_emission_day_coverage':[float(a['emission_day'][0]),float(a['emission_day'][-1])],'PN_GTI_exposure_seconds':float(sum(e-s for s,e in spans)*86400),'PN_GTI_covered':coverage(a,spans),'published_window_day':[float(x) for x in postprocess.WINDOW],'published_window_covered':coverage(a,[postprocess.WINDOW]),'definition':'Exact trapezoidal integration/extrema of native-derived scalars represented as piecewise-linear curves on arrival time, using every native knot and exact interval endpoints. No extrapolation. Nonlinear primitive-first/light-time quadrature differences remain a separate final-reference qualification.'}
        if result['PN_GTI_covered']:
            result['PN_GTI_weighted_mean']={k:float(v) for k,v in postprocess.stats(a,spans).items()}
