            result['individual_PN_frames']={}
            for frame in np.unique(gti['frame']):
                z=gti[gti['frame']==frame];windows=list(zip(z['start_mjd_utc']-postprocess.ORIGIN,z['stop_mjd_utc']-postprocess.ORIGIN))
                result['individual_PN_frames'][str(frame)]={'exposure_seconds':float(sum(e-s for s,e in windows)*86400),'weighted_mean':{k:float(v) for k,v in postprocess.stats(a,windows).items()},'extrema':extrema(a,windows)}
        if result['published_window_covered']:
            result['published_window_extrema']=extrema(a,[postprocess.WINDOW])
            result['published_window_mean']={k:float(v) for k,v in postprocess.stats(a,[postprocess.WINDOW]).items()}
